<?php
declare(strict_types=1);
require __DIR__ . '/../src/seed.php';
require __DIR__ . '/../src/domain.php';
require __DIR__ . '/../src/store.php';
$passed=0;
function test(string $name, callable $fn): void { global $passed; try{$fn();echo "PASS $name\n";$passed++;}catch(Throwable $e){fwrite(STDERR,"FAIL $name: {$e->getMessage()}\n");exit(1);} }
function check(bool $value, string $message='Assertion failed'): void {if(!$value)throw new RuntimeException($message);}
function rejects(callable $fn, string $contains=''): void {try{$fn();}catch(DomainError $e){check(!$contains||str_contains($e->getMessage(),$contains),$e->getMessage());return;}throw new RuntimeException('Expected domain rejection');}
function event_cmd(array $ids): array {return ['type'=>'create_event','name'=>'Prueba parcial','place'=>'Escenario A','responsible'=>'Krew QA','vehicle'=>'Camión QA','start'=>date('Y-m-d',strtotime('+1 day')).'T10:00','end'=>date('Y-m-d',strtotime('+2 days')).'T10:00','assetIds'=>$ids];}
function asset(array $s,string $id): array {return $s['assets'][entity_index($s['assets'],$id)];}
test('Inventario demo consistente, identificadores únicos, piezas sin doble conteo',function(){ $s=seed_state();check(count($s['assets'])===73);check(count(array_unique(array_column($s['assets'],'id')))===73);foreach($s['kits'] as $k){check(count($k['expectedIds'])===14);foreach($k['expectedIds'] as $id)check(asset($s,$id)['kitId']===$k['id']);} });
test('Salida parcial conserva identidad y no mueve las piezas restantes',function(){ $s=seed_state();$s=apply_command($s,event_cmd(['TAM-SCM-001-BD','TAM-SCM-001-T10']),'QA');check(asset($s,'TAM-SCM-001-BD')['status']==='reserved');check(asset($s,'TAM-SCM-001-T12')['status']==='available');check(!$s['kits'][0]['assembled']);check($s['revision']===1); });
test('Un kit completo puede reservarse como sus 14 activos reales',function(){ $s=seed_state();$s=apply_command($s,event_cmd($s['kits'][0]['expectedIds']),'QA');check(count(array_filter($s['assets'],fn($a)=>$a['status']==='reserved'))===14);check(count(end($s['events'])['items'])===14); });
test('Evita reservar dos veces una pieza entre eventos',function(){ $s=apply_command(seed_state(),event_cmd(['TAM-SCM-001-BD']),'QA');rejects(fn()=>apply_command($s,event_cmd(['TAM-SCM-001-BD']),'Otro encargado'),'ya está'); });
test('Rechaza equipos duplicados en una orden',function(){rejects(fn()=>apply_command(seed_state(),event_cmd(['MAR-1960A-001','MAR-1960A-001']),'QA'),'repetidos');});
test('Rechaza equipo fuera de servicio y valida toda la selección antes de mutar',function(){ $s=seed_state();rejects(fn()=>apply_command($s,event_cmd(['MAR-1960A-001','HW-BOOM-008']),'QA'),'revisión');check(asset($s,'MAR-1960A-001')['status']==='available'); });
test('No admite devolución sin salida física',function(){ $s=apply_command(seed_state(),event_cmd(['MAR-1960A-001']),'QA');$e=end($s['events']);rejects(fn()=>apply_command($s,['type'=>'return','eventId'=>$e['id'],'assetIds'=>['MAR-1960A-001']],'QA'),'aún no ha salido'); });
test('Salida y retorno parcial actualizan evento, ubicación y auditoría',function(){ $s=apply_command(seed_state(),event_cmd(['TAM-SCM-001-BD','TAM-SCM-001-T10']),'Krew QA');$id=end($s['events'])['id'];$s=apply_command($s,['type'=>'dispatch','eventId'=>$id,'assetIds'=>['TAM-SCM-001-BD']],'Encargado');check(asset($s,'TAM-SCM-001-BD')['location']==='Escenario A');check(asset($s,'TAM-SCM-001-T10')['status']==='reserved');$s=apply_command($s,['type'=>'return','eventId'=>$id,'assetIds'=>['TAM-SCM-001-BD'],'condition'=>'ok'],'Bodega');check(asset($s,'TAM-SCM-001-BD')['status']==='available');check(asset($s,'TAM-SCM-001-BD')['eventId']===null);check($s['movements'][0]['actor']==='Bodega'); });
test('Un daño bloquea disponibilidad hasta revisión técnica',function(){ $s=seed_state();$s=apply_command($s,['type'=>'return','eventId'=>'EVT-DEMO-002','assetIds'=>['MAR-1960A-003'],'condition'=>'damage','note'=>'Rueda suelta'],'QA');check(asset($s,'MAR-1960A-003')['status']==='maintenance');rejects(fn()=>apply_command($s,event_cmd(['MAR-1960A-003']),'QA'));$s=apply_command($s,['type'=>'maintenance','assetIds'=>['MAR-1960A-003'],'ready'=>true,'note'=>'Rueda reparada'],'Técnico');check(asset($s,'MAR-1960A-003')['status']==='available'); });
test('Un faltante no se convierte en stock disponible y puede recuperarse',function(){ $cmd=['type'=>'return','eventId'=>'EVT-DEMO-002','assetIds'=>['MAR-1960A-003'],'condition'=>'missing','note'=>'Quedó en recinto'];$s=apply_command(seed_state(),$cmd,'QA');check(asset($s,'MAR-1960A-003')['status']==='missing');check(asset($s,'MAR-1960A-003')['eventId']==='EVT-DEMO-002');$cmd['condition']='ok';$s=apply_command($s,$cmd,'QA');check(asset($s,'MAR-1960A-003')['status']==='available'); });
test('Daños y faltantes requieren descripción',function(){rejects(fn()=>apply_command(seed_state(),['type'=>'return','eventId'=>'EVT-DEMO-002','assetIds'=>['MAR-1960A-003'],'condition'=>'damage'],'QA'),'Describe');});
test('No permite mover un activo usando otro evento',function(){rejects(fn()=>apply_command(seed_state(),['type'=>'return','eventId'=>'EVT-DEMO-001','assetIds'=>['MAR-1960A-003']],'QA'),'no está asignado');});
test('Reasignación no permite armar un kit incompleto',function(){ $s=apply_command(seed_state(),['type'=>'assign_kit','assetId'=>'TAM-SCM-001-T12','kitId'=>'TAM-SCM-002'],'QA');check(asset($s,'TAM-SCM-001-T12')['kitId']==='TAM-SCM-002');rejects(fn()=>apply_command($s,['type'=>'kit_mode','kitId'=>'TAM-SCM-001','assembled'=>true],'QA'),'Faltan'); });
test('Pieza fuera de bodega no se reasigna a otro kit',function(){rejects(fn()=>apply_command(seed_state(),['type'=>'assign_kit','assetId'=>'MAR-1960A-003','kitId'=>'TAM-SCM-001'],'QA'),'disponibles');});
test('Liberar una reserva habilita la pieza sin simular una devolución',function(){ $s=apply_command(seed_state(),event_cmd(['MAR-1960A-001']),'QA');$id=end($s['events'])['id'];$s=apply_command($s,['type'=>'release','eventId'=>$id,'assetIds'=>['MAR-1960A-001']],'QA');check(asset($s,'MAR-1960A-001')['status']==='available');check(end($s['events'])['items'][0]['status']==='released'); });
test('Fechas invertidas y códigos repetidos se rechazan',function(){ $c=event_cmd(['MAR-1960A-001']);$c['end']='2020-01-01T10:00';rejects(fn()=>apply_command(seed_state(),$c,'QA'),'posterior');rejects(fn()=>apply_command(seed_state(),['type'=>'create_asset','code'=>'MAR-1960A-001','name'=>'Duplicado'],'QA'),'ya existe'); });
test('La pieza conserva su historial al separarse del kit',function(){ $s=apply_command(seed_state(),['type'=>'kit_mode','kitId'=>'TAM-SCM-001','assembled'=>false],'QA');check(count($s['assets'])===73);check(asset($s,'TAM-SCM-001-T12')['kitId']==='TAM-SCM-001');$s=apply_command($s,['type'=>'kit_mode','kitId'=>'TAM-SCM-001','assembled'=>true],'QA');check($s['kits'][0]['assembled']);check(count($s['movements'])===3); });
test('Crear un kit agrupa activos existentes sin duplicar stock',function(){ $s=apply_command(seed_state(),['type'=>'create_kit','name'=>'Kit escenario B','assetIds'=>['HW-BOOM-001','HW-RECT-001']],'QA');$k=end($s['kits']);check(count($s['assets'])===73);check(count($s['kits'])===3);check(asset($s,'HW-BOOM-001')['kitId']===$k['id']);check(count($k['expectedIds'])===2); });
$dbFile=sys_get_temp_dir().'/kb-test-'.bin2hex(random_bytes(6)).'.sqlite';
try {
    $store=new SqlStore(['dsn'=>'sqlite:'.$dbFile]);$store->migrate();$store->save(seed_state());
    test('SQL persiste entre conexiones independientes',function()use($store,$dbFile){$s=$store->command(event_cmd(['MAR-1960A-001']),'Operador A',0);$other=new SqlStore(['dsn'=>'sqlite:'.$dbFile]);check($other->read()['revision']===1);check(asset($other->read(),'MAR-1960A-001')['status']==='reserved');});
    test('Una revisión antigua no sobrescribe cambios de otro operador',function()use($store){rejects(fn()=>$store->command(event_cmd(['MAR-1960A-002']),'Operador B',0),'CONFLICT');check(asset($store->read(),'MAR-1960A-002')['status']==='available');});
    test('Una operación inválida revierte la transacción sin alterar inventario',function()use($store){$before=$store->read();rejects(fn()=>$store->command(event_cmd(['MAR-1960A-002','HW-BOOM-008']),'QA',$before['revision']));check($store->read()===$before);});
    test('SQL limita intentos repetidos de acceso',function()use($store){for($i=0;$i<15;$i++)$store->authAttempt('qa');rejects(fn()=>$store->authAttempt('qa'),'Demasiados');});
} finally {if(is_file($dbFile))unlink($dbFile);}
echo "\n$passed tests passed. PHP ".PHP_VERSION."\n";
